CREATE OR REPLACE FUNCTION public.bootstrap_candidate_identity(p_auth_user_id uuid, p_full_name text, p_email text, p_tenant_id uuid DEFAULT NULL::uuid, p_role_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(person_id uuid, tenant_membership_id uuid, role_assignment_id uuid, first_login_state_person_id uuid, candidate_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_person_id uuid;
  v_tenant_membership_id uuid;
  v_role_assignment_id uuid;
  v_first_login_state_person_id uuid;
  v_candidate_id uuid;
BEGIN
  SET LOCAL row_security = off;

  -- 1. People (idempotent)
  SELECT id INTO v_person_id
  FROM public.people
  WHERE auth_user_id = p_auth_user_id;

  IF v_person_id IS NULL THEN
    INSERT INTO public.people (auth_user_id, full_name, email, status)
    VALUES (p_auth_user_id, p_full_name, p_email, 'active')
    RETURNING id INTO v_person_id;
  END IF;

  -- 2. Tenant membership (idempotent)
  IF p_tenant_id IS NOT NULL THEN
    SELECT id INTO v_tenant_membership_id
    FROM public.tenant_memberships
    WHERE person_id = v_person_id
      AND tenant_id = p_tenant_id;

    IF v_tenant_membership_id IS NULL THEN
      INSERT INTO public.tenant_memberships (
        person_id, tenant_id, status, joined_at
      ) VALUES (
        v_person_id, p_tenant_id, 'active', now()
      )
      RETURNING id INTO v_tenant_membership_id;
    END IF;
  END IF;

  -- 3. Role assignment (idempotent)
  IF p_role_id IS NOT NULL THEN
    SELECT id INTO v_role_assignment_id
    FROM public.role_assignments
    WHERE person_id = v_person_id
      AND role_id = p_role_id;

    IF v_role_assignment_id IS NULL THEN
      INSERT INTO public.role_assignments (
        person_id, role_id, tenant_id, assigned_at
      ) VALUES (
        v_person_id, p_role_id, p_tenant_id, now()
      )
      RETURNING id INTO v_role_assignment_id;
    END IF;
  END IF;

  -- 4. First login state (idempotent)
  SELECT person_id INTO v_first_login_state_person_id
  FROM public.first_login_state
  WHERE person_id = v_person_id;

  IF v_first_login_state_person_id IS NULL THEN
    INSERT INTO public.first_login_state (
      person_id, signup_origin, must_change_password, first_login_completed
    ) VALUES (
      v_person_id, 'self_signup', false, false
    )
    RETURNING person_id INTO v_first_login_state_person_id;
  END IF;

  -- 5. Candidate (idempotent)
  IF p_tenant_id IS NOT NULL THEN
    SELECT id INTO v_candidate_id
    FROM public.candidates
    WHERE person_id = v_person_id
      AND tenant_id = p_tenant_id;

    IF v_candidate_id IS NULL THEN
      INSERT INTO public.candidates (person_id, tenant_id, status)
      VALUES (v_person_id, p_tenant_id, 'active')
      RETURNING id INTO v_candidate_id;
    END IF;
  END IF;

  RETURN QUERY
  SELECT v_person_id, v_tenant_membership_id, v_role_assignment_id,
         v_first_login_state_person_id, v_candidate_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.handle_new_auth_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_meta jsonb;
  v_full_name text;
  v_email text;
BEGIN
  v_meta := coalesce(new.raw_user_meta_data, '{}'::jsonb);
  v_email := new.email;
  v_full_name := v_meta ->> 'full_name';
  IF v_full_name IS NULL OR v_full_name = '' THEN
    v_full_name := v_meta ->> 'name';
  END IF;
  IF v_full_name IS NULL OR v_full_name = '' THEN
    v_full_name := split_part(v_email, '@', 1);
  END IF;

  IF EXISTS (SELECT 1 FROM public.people WHERE auth_user_id = new.id) THEN
    UPDATE public.people
    SET email = new.email, full_name = v_full_name
    WHERE auth_user_id = new.id
      AND (email IS DISTINCT FROM new.email
           OR full_name IS DISTINCT FROM v_full_name);
  ELSE
    INSERT INTO public.people (id, auth_user_id, full_name, email, status)
    VALUES (gen_random_uuid(), new.id, v_full_name, v_email, 'active');
  END IF;

  RETURN new;
END;
$function$

CREATE OR REPLACE FUNCTION public.is_valid_cnpj(p_value text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_digits text;
  v_d1 int; v_d2 int; v_sum int; v_rest int; v_i int;
  v_weights1 int[] := ARRAY[5,4,3,2,9,8,7,6,5,4,3,2];
  v_weights2 int[] := ARRAY[6,5,4,3,2,9,8,7,6,5,4,3,2];
BEGIN
  v_digits := public.normalize_cnpj(p_value);
  IF v_digits IS NULL OR length(v_digits) <> 14 THEN
    RETURN false;
  END IF;
  IF v_digits ~ '^(.)\1{13}$' THEN
    RETURN false;
  END IF;

  v_sum := 0;
  FOR v_i IN 1..12 LOOP
    v_sum := v_sum + (substring(v_digits, v_i, 1))::int * v_weights1[v_i];
  END LOOP;
  v_rest := v_sum % 11;
  v_d1 := CASE WHEN v_rest < 2 THEN 0 ELSE 11 - v_rest END;
  IF v_d1 <> (substring(v_digits, 13, 1))::int THEN
    RETURN false;
  END IF;

  v_sum := 0;
  FOR v_i IN 1..13 LOOP
    v_sum := v_sum + (substring(v_digits, v_i, 1))::int * v_weights2[v_i];
  END LOOP;
  v_rest := v_sum % 11;
  v_d2 := CASE WHEN v_rest < 2 THEN 0 ELSE 11 - v_rest END;
  IF v_d2 <> (substring(v_digits, 14, 1))::int THEN
    RETURN false;
  END IF;

  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.is_valid_cpf(p_value text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_digits text;
  v_d1 int; v_d2 int; v_sum int; v_rest int; v_i int;
BEGIN
  v_digits := public.normalize_cpf(p_value);
  IF v_digits IS NULL OR length(v_digits) <> 11 THEN
    RETURN false;
  END IF;
  IF v_digits ~ '^(.)\1{10}$' THEN
    RETURN false;
  END IF;

  v_sum := 0;
  FOR v_i IN 1..9 LOOP
    v_sum := v_sum + (substring(v_digits, v_i, 1))::int * (11 - v_i);
  END LOOP;
  v_rest := (v_sum * 10) % 11;
  v_d1 := CASE WHEN v_rest = 10 THEN 0 ELSE v_rest END;
  IF v_d1 <> (substring(v_digits, 10, 1))::int THEN
    RETURN false;
  END IF;

  v_sum := 0;
  FOR v_i IN 1..10 LOOP
    v_sum := v_sum + (substring(v_digits, v_i, 1))::int * (12 - v_i);
  END LOOP;
  v_rest := (v_sum * 10) % 11;
  v_d2 := CASE WHEN v_rest = 10 THEN 0 ELSE v_rest END;
  IF v_d2 <> (substring(v_digits, 11, 1))::int THEN
    RETURN false;
  END IF;

  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.repair_candidate_chain(p_person_id uuid, p_tenant_id uuid DEFAULT NULL::uuid, p_role_code text DEFAULT 'candidato'::text)
 RETURNS TABLE(person_id uuid, tenant_membership_id uuid, role_assignment_id uuid, candidate_id uuid, created_membership boolean, created_assignment boolean, created_candidate boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_tenant_membership_id uuid;
  v_role_assignment_id   uuid;
  v_candidate_id         uuid;
  v_role_id              uuid;
  v_resolved_tenant_id   uuid;
  v_created_membership   boolean := false;
  v_created_assignment   boolean := false;
  v_created_candidate    boolean := false;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.people WHERE id = p_person_id) THEN
    RAISE EXCEPTION 'repair_candidate_chain: person % não encontrada', p_person_id;
  END IF;

  IF p_tenant_id IS NOT NULL THEN
    v_resolved_tenant_id := p_tenant_id;
  ELSE
    SELECT tm.tenant_id INTO v_resolved_tenant_id
    FROM public.tenant_memberships tm
    WHERE tm.person_id = p_person_id
      AND tm.status = 'active'
    ORDER BY tm.joined_at DESC NULLS LAST
    LIMIT 1;
  END IF;

  IF v_resolved_tenant_id IS NULL THEN
    RAISE EXCEPTION 'repair_candidate_chain: nenhum tenant resolvido para person %', p_person_id;
  END IF;

  SELECT id INTO v_tenant_membership_id
  FROM public.tenant_memberships
  WHERE person_id = p_person_id
    AND tenant_id = v_resolved_tenant_id;

  IF v_tenant_membership_id IS NULL THEN
    INSERT INTO public.tenant_memberships (person_id, tenant_id, status, joined_at)
    VALUES (p_person_id, v_resolved_tenant_id, 'active', now())
    RETURNING id INTO v_tenant_membership_id;
    v_created_membership := true;
  END IF;

  SELECT id INTO v_role_id
  FROM public.roles
  WHERE name = p_role_code
  LIMIT 1;

  IF v_role_id IS NOT NULL THEN
    SELECT id INTO v_role_assignment_id
    FROM public.role_assignments
    WHERE person_id = p_person_id
      AND role_id = v_role_id
      AND (tenant_id = v_resolved_tenant_id OR tenant_id IS NULL);

    IF v_role_assignment_id IS NULL THEN
      INSERT INTO public.role_assignments (person_id, role_id, tenant_id, assigned_at)
      VALUES (p_person_id, v_role_id, v_resolved_tenant_id, now())
      RETURNING id INTO v_role_assignment_id;
      v_created_assignment := true;
    END IF;
  END IF;

  SELECT id INTO v_candidate_id
  FROM public.candidates
  WHERE person_id = p_person_id
    AND tenant_id = v_resolved_tenant_id;

  IF v_candidate_id IS NULL THEN
    INSERT INTO public.candidates (person_id, tenant_id, status, created_at)
    VALUES (p_person_id, v_resolved_tenant_id, 'active', now())
    RETURNING id INTO v_candidate_id;
    v_created_candidate := true;
  END IF;

  person_id := p_person_id;
  tenant_membership_id := v_tenant_membership_id;
  role_assignment_id := v_role_assignment_id;
  candidate_id := v_candidate_id;
  created_membership := v_created_membership;
  created_assignment := v_created_assignment;
  created_candidate := v_created_candidate;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
    begin
      new.updated_at = now();
      return new;
    end;
    $function$
